def count_palindromes(limit):
    """How many integers in 1..limit-1 read the same in both directions."""
    found = 0
    for n in range(1, limit):
        rev = 0
        m = n
        while m > 0:
            rev = rev * 10 + m % 10
            m = m // 10
        if rev == n:
            found += 1
    return found

